arguments.new_string:
osc, sgr = match.groups()
if sgr and len(sgr) == 1 and '0' <= sgr <= '?':
    position = end
    continue

if start > position:
    yield _AnsiToken(ansi_text[position:start])
if sgr:
    if sgr == "(":
        position = end + 1
        continue
    if sgr.endswith("m"):
        yield _AnsiToken("", sgr[1:-1], osc)
else:
    yield _AnsiToken("", sgr, osc)
position = end

